import 'dart:ui';class VisionState {  final String selectedTheme;  final String selectedLanguage;  final bool isPremium;  final Locale locale;  final int launchCount;  VisionState({    required this.selectedTheme,    required this.selectedLanguage,    required this.isPremium,    required this.locale,    required this.launchCount,  });  factory VisionState.initial() => VisionState(    selectedTheme: 'light',    selectedLanguage: 'en',    isPremium: false,    locale: const Locale('en'),    launchCount: 0,  );  VisionState copyWith({    String? selectedTheme,    String? selectedLanguage,    bool? isPremium,    Locale? locale,    int? launchCount,  }) {    return VisionState(      selectedTheme: selectedTheme ?? this.selectedTheme,      selectedLanguage: selectedLanguage ?? this.selectedLanguage,      isPremium: isPremium ?? this.isPremium,      locale: locale ?? this.locale,      launchCount: launchCount ?? this.launchCount,    );  }}